#include <immintrin.h>
#include <stddef.h>

// Dot product of two fp32 vectors; d must be a multiple of 8 here.
float dot_avx2(const float *a, const float *b, size_t d) {
    __m256 acc = _mm256_setzero_ps();
    for (size_t i = 0; i < d; i += 8) {
        __m256 va = _mm256_loadu_ps(a + i);
        __m256 vb = _mm256_loadu_ps(b + i);
        acc = _mm256_fmadd_ps(va, vb, acc);       // acc += va * vb, 8 lanes
    }
    // Horizontal sum: 8 lanes to 4, then 2, then 1.
    __m128 s = _mm_add_ps(_mm256_castps256_ps128(acc),
                          _mm256_extractf128_ps(acc, 1));
    s = _mm_add_ps(s, _mm_movehl_ps(s, s));      // lanes 0,1 += lanes 2,3
    s = _mm_add_ss(s, _mm_shuffle_ps(s, s, 1));  // lane 0 += lane 1
    return _mm_cvtss_f32(s);
}

// Simplified from hnswlib space_ip.h
float ip_distance_residuals(const float *a, const float *b, size_t qty) {
    size_t qty16 = qty >> 4 << 4;            // round down to a multiple of 16
    float res = ip_simd16(a, b, qty16);       // SIMD body (AVX-512, AVX or SSE)
    size_t left = qty - qty16;                // elements the body skipped
    float tail = ip_scalar(a + qty16, b + qty16, left);
    return 1.0f - (res + tail);               // hnswlib inner-product distance
}

